#define PI 3.141592
#define TAU (2.*PI)
#define SIN(x) (sin(x)*0.5 + 0.5)
#define BUMP_EPS 0.0001
#define sabsk(x, k) sqrt(x * x + k * k)
#define sabs(x) (sabsk(x, 0.1))
#define S(a, b, x) smoothstep(a, b, x)


// Utility Functions
mat2 rot(float a) { 
    return mat2(cos(a), -sin(a), sin(a), cos(a)); 
}

float smin(float a, float b, float k) {
    float h = clamp((a - b) / k * 0.5 + 0.5, 0.0, 1.0);
    return mix(a, b, h) - h * (1.0 - h) * k;
}

float smax(float a, float b, float k) {
    float h = max(k - abs(a - b), 0.0);
    return max(a, b) + h * h * 0.25 / k;
}

float pMod(float p, float size) {
    float halfsize = size * 0.5;
    p = mod(p + halfsize, size) - halfsize;
    return p;
}

// Noise Functions
float n21(vec2 p) {
    return fract(sin(dot(p, vec2(524.423, 123.34))) * 3228324.345);
}

float noise(vec2 n) {
    const vec2 d = vec2(0.0, 1.0);
    vec2 b = floor(n);
    vec2 f = mix(vec2(0.0), vec2(1.0), fract(n));
    return mix(
        mix(n21(b), n21(b + d.yx), f.x),
        mix(n21(b + d.xy), n21(b + d.yy), f.x),
        f.y
    );
}

// Folding and Stereographic Transform
vec3 fold(vec3 p) {
    float c = cos(PI / 5.0), s = sqrt(0.75 - c * c);
    vec3 n = vec3(-0.5, -c, s);
    p = abs(p);
    p -= 2.0 * min(0.0, dot(p, n)) * n;
    p.xy = abs(p.xy);
    p -= 2.0 * min(0.0, dot(p, n)) * n;
    p.xy = abs(p.xy);
    p -= 2.0 * min(0.0, dot(p, n)) * n;
    return p;
}

vec4 inverseStereographic(vec3 p, out float k) {
    k = 2.0 / (1.0 + dot(p, p));
    return vec4(k * p, k - 1.0);
}

float fTorus(vec4 p4) {
    float d1 = length(p4.xy) / length(p4.zw) - 1.0;
    float d2 = length(p4.zw) / length(p4.xy) - 1.0;
    float d = (d1 < 0.0) ? -d1 : d2;
    d /= PI;
    return d;
}

float fixDistance(float d, float k) {
    float sn = sign(d);
    d = abs(d);
    d = d / k * 1.82;
    d += 1.0;
    d = pow(d, 0.5);
    d -= 1.0;
    d *= 5.0 / 3.0;
    d *= sn;
    return d;
}

// Distance Function
float map(vec3 p) {   
    p.xy *= rot(0.1 * iTime);
    p.xz *= rot(0.3 * iTime);

    vec3 bp0 = p;
    p = fold(p);

    vec3 bp = p;
    float k;
    p = bp0;
    p.x = sabsk(p.x, 1.2) - 2.0;
    p.xy *= rot(p.z * 0.3 + iTime);

    vec4 p4 = inverseStereographic(p, k);
    p4.y -= SIN(0.33 * iTime);
    p4.zy *= rot(0.25 * iTime);
    p4.xw *= rot(0.25 * iTime);

    float d = fTorus(p4);
    d = abs(d) - 0.12;
    d = fixDistance(d, k);

    p = bp;

    p.xy *= rot(1.0 * p.z * 0.5 + iTime);
    p.xz *= rot(0.5 * p.y + 0.5 * iTime);

    p.xy -= sin(p.z * mix(2.0, 15.0, SIN(0.7 * iTime)) + iTime) * 0.2;
    bp = p;

    p.x -= 0.3;
    p.xz = sabsk(p.xz, 0.4) - 0.5 * SIN(iTime);
    p.xz *= rot(iTime);

    p.xz -= vec2(sin(0.4 * iTime) * 0.3, cos(0.3 * iTime) * 0.4);
    float d1 = length(p) - 1.4;

    p = bp;

    p.x += 0.8;
    p.xy = sabsk(p.xy, 0.4) + 1.0 * SIN(0.5 * iTime);
    p.xz += vec2(sin(iTime) * 0.4, cos(iTime) * 1.5);

    float d2 = smax(d1, -(length(p) - 1.4), 1.0);

    d = smax(d, (d2) - 0.5, 0.5);

    return d * 0.8;
}

// Enhanced Palette Function
vec3 pal(float x) {
    return 0.5 + 0.5 * cos(TAU * (vec3(1.0, 1.0, 1.0) * x + vec3(0.0, 0.3, 0.5)));
}

// Ray Direction Calculation
vec3 getRayDir(vec2 uv, vec3 ro, vec3 lookat, float z) {
    vec3 f = normalize(lookat - ro);  // forward vector
    vec3 r = normalize(cross(vec3(0, 1, 0), f)); // right vector
    vec3 u = cross(f, r); // up vector
    vec3 c = ro + f * z; // center of virtual screen
    vec3 i = c + uv.x * r + uv.y * u; // point on screen
    vec3 rd = normalize(i - ro); // ray direction
    return rd;
}

// Normal Calculation via Gradient
vec3 getNormal(vec3 p) {
    float d = map(p);
    vec3 eps = vec3(BUMP_EPS, 0.0, 0.0);
    vec3 n;
    n.x = map(p + vec3(eps.x, eps.yz)) - map(p - vec3(eps.x, eps.yz));
    n.y = map(p + vec3(eps.y, eps.xz)) - map(p - vec3(eps.y, eps.xz));
    n.z = map(p + vec3(eps.z, eps.xy)) - map(p - vec3(eps.z, eps.xy));
    return normalize(n);
}

// Shadow Calculation
float shadow(vec3 ro, vec3 rd, float k) {
    float res = 1.0;
    float t = 0.01;
    for(int i = 0; i < 32; i++) {
        float h = map(ro + rd * t);
        if(h < 0.001) {
            return 0.0;
        }
        res = min(res, 10.0 * h / t);
        t += clamp(h, 0.02, 0.1);
        if(t > k) break;
    }
    return res;
}

// Ambient Occlusion
float ambientOcclusion(vec3 p, vec3 n) {
    float ao = 0.0;
    float scale = 1.0;
    for(int i = 1; i <= 5; i++) {
        float d = map(p + n * float(i) * 0.1);
        ao += (float(i) * 0.1 - d) * 0.2;
    }
    return clamp(ao, 0.0, 1.0);
}

// Main Rendering Function
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalized Device Coordinates
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    // Time Variable
    float tt = iTime + 30.0;

    // Camera Setup
    vec3 ro = vec3(0.0, 0.0, -4.0); // Ray Origin
    vec3 lookat = vec3(0.0, 0.0, 0.0); // Look-at Point
    vec3 rd = getRayDir(uv, ro, lookat, 1.0); // Ray Direction

    // Raymarching Variables
    float t = 0.0;
    float MAX_DIST = 15.0;
    float EPSILON = 0.001;
    int MAX_STEPS = 100;

    vec3 col = vec3(0.0);
    vec3 p;
    float d;

    // Light Parameters
    vec3 lightPos = vec3(5.0, 5.0, -5.0);
    vec3 lightColor = vec3(1.0, 1.0, 1.0);
    vec3 ambient = vec3(0.1);

    // Raymarch Loop
    for(int i = 0; i < MAX_STEPS; i++) {
        p = ro + rd * t;
        d = map(p);

        if(abs(d) < EPSILON) {
            // Compute Normal
            vec3 n = getNormal(p);

            // Compute Lighting
            vec3 lightDir = normalize(lightPos - p);
            float diff = max(dot(n, lightDir), 0.0);

            // Compute Shadows
            float sh = shadow(p + n * EPSILON * 4.0, lightDir, length(lightPos - p));

            // Compute Ambient Occlusion
            float ao = ambientOcclusion(p, n);

            // Combine Lighting
            vec3 diffuse = diff * lightColor;
            vec3 finalColor = (ambient + sh * diffuse) * pal(dot(n, vec3(0.984,1.000,0.000)));
            finalColor *= ao;

            // Accumulate Color
            col += finalColor;
            break;
        }

        col += vec3(0.002) / pow(t + 1.0, 1.2); // Add subtle color accumulation

        t += max(d * 0.5, 0.01);
        if(t > MAX_DIST) break;
    }

    // Background Color
    if(t > MAX_DIST) {
        col += vec3(1.000,0.000,0.000) * S(10.0, 4.0, t); // Deep space background
    }

    // Post-Processing: Tone Mapping and Gamma Correction
    col = pow(col, vec3(0.4545)); // Gamma Correction (gamma 2.2)
    fragColor = vec4(col, 1.0);
}
